TLM.f("Sancti/08-07",{"officium":"S. Cajetani Confessoris","rule":["vide C5;","9 lectiones","Gloria"],"fallback":"Commune/C5","from":{"Lectio":"Commune/C5","Graduale":"Commune/C5","GradualeP":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui beáto Cajetáno Confessóri tuo apostólicam vivéndi formam imitári tribuísti: da nobis, ejus intercessióne et exémplo, in te semper confídere et sola cæléstia desideráre."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 31:8-11"},{"k":"text","la":"Beátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum."}],"Graduale":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem. Allelúja, allelúja"},{"k":"ref","la":"Ja 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 6:24-33"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nemo potest duóbus dóminis servíre: aut enim unum ódio habébit, et álterum díliget: aut unum sustinébit, et álterum contémnet. Non potéstis Deo servíre et mammónæ. Ideo dico vobis, ne sollíciti sitis ánimæ vestræ, quid manducétis, neque córpori vestro, quid induámini. Nonne ánima plus est quam esca: et corpus plus quam vestiméntum? Respícite volatília cœli, quóniam non serunt neque metunt neque cóngregant in hórrea: et Pater vester cœléstis pascit illa. Nonne vos magis pluris estis illis? Quis autem vestrum cógitans potest adjícere ad statúram suam cúbitum unum? Et de vestiménto quid sollíciti estis? Consideráte lília agri, quómodo crescunt: non labórant neque nent. Dico autem vobis, quóniam nec Sálomon in omni glória sua coopértus est sicut unum ex istis. Si autem fænum agri, quod hódie est et cras in clíbanum míttitur, Deus sic vestit: quanto magis vos módicæ fídei? Nolíte ergo sollíciti esse, dicéntes: Quid manducábimus aut quid bibémus aut quo operiémur? Hæc enim ómnia gentes inquírunt. Scit enim Pater vester, quia his ómnibus indigétis. Quǽrite ergo primum regnum Dei et justítiam ejus: et hæc ómnia adjiciéntur vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Præsta nobis, quǽsumus, omnípotens Deus: ut nostræ humilitátis oblátio et pro tuórum tibi grata sit honóre Sanctórum, et nos córpore páriter et mente puríficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 24:46-47"},{"k":"text","la":"Beátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut, qui cœléstia aliménta percépimus, intercedénte beáto Caietáno Confessóre tuo, per hæc contra ómnia advérsa muniámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"52236fd7918c9b03":{"t":"Ps 36, 30-31, Ps 36, 1\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu. (Ps 36, 1) Ne zaviđaj sreći grešnika i ne žesti se radi zlotvora.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu."},"99403e13f9b78553":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženom Kajetanu priznavaocu svome dao da nasljeduje apostolski oblik života, daj da se po njegovu zagovoru i primjeru uvijek uzdamo u tebe i želimo samo ono što je nebesko.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"d0743eab00685bfc":{"t":"Sir 31, 8-11\nČitanje knjige Mudrosti. Blago čovjeku koji se nađe bez ljage i ne teži za zlatom, niti se uzda u novac i blago. Tko je taj, da ga pohvalimo? U svojem je životu učinio divna djela. Tko je u tome prokušan i savršen bit će uvijek slavan. Mogao je sagriješiti, ali nije sagriješio, učiniti zlo, ali nije počinio. Zato priznaje njegova djela Gospodin, a njegovih će se milostinja sjećati sve skupine svetih."},"929d73ef8c983301":{"t":"Ps 91, 13-14, Ps 91, 3\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik u domu Gospodnjem. (Ps 91, 3) Jutrom naviješta milosrđe tvoje i noću tvoju vjernost.\n\nJak 1, 12\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji nadvlada napast, jer kad bude prokušan, primit će krunu života. <i>Aleluja</i>."},"7f3eafb4a57c0395":{"t":"Mt 6, 24-33\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Nitko ne može služiti dvama gospodarima, jer ili će jednoga mrziti, a drugoga ljubiti, ili će pristajati uz jednoga, a prezirati drugoga. Ne možete služiti Bogu i bogatstvu! Zato vam kažem: Ne brinite se toliko za svoj život što ćete jesti, ni za svoje tijelo što ćete obući. Zar život ne vrijedi više nego jelo, i tijelo više nego odijelo? Pogledajte ptice: niti siju, niti žanju, niti sabiru u žitnice, a hrani ih vaš nebeski Otac. Niste li vi daleko vrjedniji od njih? A tko od vas može svojom brigom dodati svojem rastu i jedan lakat? I za odijelo što vas toliko mori briga? Gledajte kako rastu ljiljani u polju: niti se trude, niti predu, a kažem vam da se ni Salamon u svojem punom sjaju nije odijevao kao jedan od njih. Pa ako Bog tako odijeva poljsku travu koja danas jest, a već se sutra baca u peć, koliko će više vas, malovjerni? Ne brinite se dakle toliko i ne govorite: što ćemo jesti ili u što ćemo se obući? Sve to traže nevjernici. Vaš nebeski Otac zna da vam sve to treba. Tražite prije svega Božje kraljevstvo i njegovu pravdu, a sve će vam se ostalo dati."},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć."},"1e8de8be36cd864e":{"t":"Daj nam, molimo, svemogući Bože, da naš ponizni prinos bude tebi drag zbog časti tvojih svetih,i neka očisti naše tijelo i dušu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"56842ed674d6e163":{"t":"Mt 24, 46-47\nBlago slugi koga gospodar nađe budna, kad dođe. Zaista vam kažem: Postavit će ga nad svim imanjem svojim."},"963bf3b74076d707":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da nas nebeska hrana koju smo primili zagovorom blaženoga Kajetana, tvoga priznavaoca zaštiti od svih protivnosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja"},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}]}}});
